func getSortedKeys[T any](m map[int]T) []int {
	keys := make([]int, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Ints(keys)
	return keys
}

func renderKVBlock(key string, obj *kv.KVObject) string {
	return fmt.Sprintf("\"%s\"\n{\n%s}\n", key, kvToString(obj, 1))
}

func kvToString(obj *kv.KVObject, indent int) string {
	pad := strings.Repeat("\t", indent)
	var b strings.Builder
	for _, k := range obj.Keys {
		v := obj.Values[k]
		switch vv := v.(type) {
		case string:
			b.WriteString(fmt.Sprintf("%s\"%s\"\t\t\"%s\"\n", pad, k, vv))
		case *kv.KVObject:
			b.WriteString(fmt.Sprintf("%s\"%s\"\n", pad, k))
			b.WriteString(fmt.Sprintf("%s{\n", pad))
			b.WriteString(kvToString(vv, indent+1))
			b.WriteString(fmt.Sprintf("%s}\n", pad))
		}
	}
	return b.String()
}

// renderDummyBlock replaces key/Model/AttachWearables using raw template text (tolerant to non-standard formatting).
func renderDummyBlock(templateRaw, newKey, model string, wearKeys []string) string {
	out := templateRaw

	reKey := regexp.MustCompile(`"npc_dota_auto_cast_dummy_drow_ranger_\d+"`)
	out = reKey.ReplaceAllString(out, fmt.Sprintf("\"%s\"", newKey))

	reModel := regexp.MustCompile(`"Model"\s*"[^"]*"`)
	out = reModel.ReplaceAllString(out, fmt.Sprintf("\"Model\"\t\t\"%s\"", model))

	// Remove any direct Wearable entries from the template; we'll inject AttachWearables.
	reWearableLine := regexp.MustCompile(`(?m)^\s*"Wearable\d+"\s*\{[^\}]*\}\s*(//.*)?\s*$\n?`)
	out = reWearableLine.ReplaceAllString(out, "")

	var attachBuilder strings.Builder
	attachBuilder.WriteString("\t\t\"AttachWearables\"\n\t\t{\n")
	for i, id := range wearKeys {
		attachBuilder.WriteString(fmt.Sprintf("\t\t      \"Wearable%d\"\t\t{	\"ItemDef\"\t\t\"%s\"\t\t}\n", i+1, id))
	}
	attachBuilder.WriteString("\t\t}")
	attachBlock := attachBuilder.String()

	reAttach := regexp.MustCompile(`"AttachWearables"\s*\{[\s\S]*?\}`)
	if reAttach.MatchString(out) {
		out = reAttach.ReplaceAllString(out, attachBlock)
	} else {
		reCreature := regexp.MustCompile(`"Creature"\s*\{`)
		loc := reCreature.FindStringIndex(out)
		if loc != nil {
			insertPos := loc[1]
			out = out[:insertPos] + "\n" + attachBlock + out[insertPos:]
		} else {
			// fallback append at end
			out = out + "\n" + attachBlock + "\n"
		}
	}

	return out
}

